function row(cells) {
  return '<tr>' + cells.map(function (cell) { return '<td>' + cell + '</td>'; }).join('') + '</tr>';
}

function headerRow(cells) {
  return '<tr>' + cells.map(function (cell) { return '<th>' + cell + '</th>'; }).join('') + '</tr>';
}

function simpleTable(headers, rows) {
  const head = '<tr>' + headers.map(function (cell) { return '<th>' + cell + '</th>'; }).join('') + '</tr>';
  const body = rows.map(function (line) {
    return '<tr>' + line.map(function (cell) { return '<td>' + cell + '</td>'; }).join('') + '</tr>';
  }).join('');
  return '<table>' + head + body + '</table>';
}
